bool TlImportDocument::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("entity_type"))
    {
        if(!validJsonOfField(1, "entity_type", pJson["entity_type"], err, true))
            return false;
    }
    else
    {
        err="The entity_type column cannot be null";
        return false;
    }
    if(pJson.isMember("file_name"))
    {
        if(!validJsonOfField(2, "file_name", pJson["file_name"], err, true))
            return false;
    }
    else
    {
        err="The file_name column cannot be null";
        return false;
    }
    if(pJson.isMember("import_time"))
    {
        if(!validJsonOfField(3, "import_time", pJson["import_time"], err, true))
            return false;
    }
    if(pJson.isMember("end_time"))
    {
        if(!validJsonOfField(4, "end_time", pJson["end_time"], err, true))
            return false;
    }
    if(pJson.isMember("total_records"))
    {
        if(!validJsonOfField(5, "total_records", pJson["total_records"], err, true))
            return false;
    }
    if(pJson.isMember("successful_count"))
    {
        if(!validJsonOfField(6, "successful_count", pJson["successful_count"], err, true))
            return false;
    }
    if(pJson.isMember("failed_count"))
    {
        if(!validJsonOfField(7, "failed_count", pJson["failed_count"], err, true))
            return false;
    }
    if(pJson.isMember("status"))
    {
        if(!validJsonOfField(8, "status", pJson["status"], err, true))
            return false;
    }
    if(pJson.isMember("created_by"))
    {
        if(!validJsonOfField(9, "created_by", pJson["created_by"], err, true))
            return false;
    }
    return true;
}
